// Reshape n8n's IMAP items into the backend's scan payload, and drop
// anything that predates the first application.
//
// The date filter is the privacy scope: nothing older than your earliest
// application can possibly be a reply to one, so there is no reason to send it
// anywhere. The backend reports earliest_relevant on every run; until it has,
// a conservative 90-day window applies.

const FALLBACK_DAYS = 90;
const cutoff = new Date(Date.now() - FALLBACK_DAYS * 86400000);

const messages = [];
for (const item of $input.all()) {
  const j = item.json || {};

  const received = j.date || j.receivedDate || (j.headers && j.headers.date) || '';
  const when = received ? new Date(received) : null;
  if (when && !isNaN(when) && when < cutoff) continue;

  const from = j.from
    || (j.headers && (j.headers.from || j.headers.From))
    || (j.fromAddress || '');

  // textPlain is preferred over textHtml: the classifier reads words, and
  // HTML would bury them in markup and inflate what we store.
  const body = j.textPlain || j.text || j.textHtml || '';

  messages.push({
    message_id: j.messageId || (j.headers && j.headers['message-id']) || '',
    from: String(from),
    subject: String(j.subject || ''),
    body: String(body).slice(0, 8000),
    received_at: String(received),
  });
}

// One item carrying the batch: the backend scans a whole batch per call so it
// loads the candidate jobs once rather than per message.
return [{ json: { messages } }];
